// InstrumentChange represents the "instrument-change" XSD complex type.
//
// The instrument-change element type represents a change to the virtual
// instrument sound for a given score-instrument. The id attribute refers to the
// score-instrument affected by the change. All instrument-change child elements
// can also be initially specified within the score-instrument element.
type InstrumentChange struct {
	// The instrument-sound element describes the default timbre of the
	// score-instrument. This description is independent of a particular virtual
	// or MIDI instrument specification and allows playback to be shared more
	// easily between applications and libraries.
	InstrumentSound *string `xml:"instrument-sound,omitempty"`
	// The solo element is present if performance is intended by a solo
	// instrument.
	Solo *Empty `xml:"solo,omitempty"`
	// The ensemble element is present if performance is intended by an ensemble
	// such as an orchestral section. The text of the ensemble element contains
	// the size of the section, or is empty if the ensemble size is not
	// specified.
	Ensemble          *PositiveIntegerOrEmpty `xml:"ensemble,omitempty"`
	VirtualInstrument *VirtualInstrument      `xml:"virtual-instrument,omitempty"`
	ID                string                  `xml:"id,attr"`
}

// InstrumentLink represents the "instrument-link" XSD complex type.
//
// Multiple part-link elements can link a condensed part within a score file to
// multiple MusicXML parts files. For example, a "Clarinet 1 and 2" part in a
// score file could link to separate "Clarinet 1" and "Clarinet 2" part files.
// The instrument-link type distinguish which of the score-instruments within a
// score-part are in which part file. The instrument-link id attribute refers to
// a score-instrument id attribute.
type InstrumentLink struct {
	ID string `xml:"id,attr"`
}

// Interchangeable represents the "interchangeable" XSD complex type.
//
// The interchangeable type is used to represent the second in a pair of
// interchangeable dual time signatures, such as the 6/8 in 3/4 (6/8). A
// separate symbol attribute value is available compared to the time element's
// symbol attribute, which applies to the first of the dual time signatures.
type Interchangeable struct {
	TimeRelation *TimeRelation           `xml:"time-relation,omitempty"`
	Content      InterchangeableContents `xml:",any"`
	Symbol       *TimeSymbol             `xml:"symbol,attr,omitempty"`
	Separator    *TimeSeparator          `xml:"separator,attr,omitempty"`
}

// Inversion represents the "inversion" XSD complex type.
//
// The inversion type represents harmony inversions. The value is a number
// indicating which inversion is used: 0 for root position, 1 for first
// inversion, etc. The text attribute indicates how the inversion should be
// displayed in a score.
type Inversion struct {
	Value      NonNegativeInteger `xml:",chardata"`
	Text       *string            `xml:"text,attr,omitempty"`
	DefaultX   *Tenths            `xml:"default-x,attr,omitempty"`
	DefaultY   *Tenths            `xml:"default-y,attr,omitempty"`
	RelativeX  *Tenths            `xml:"relative-x,attr,omitempty"`
	RelativeY  *Tenths            `xml:"relative-y,attr,omitempty"`
	FontFamily *FontFamily        `xml:"font-family,attr,omitempty"`
	FontStyle  *FontStyle         `xml:"font-style,attr,omitempty"`
	FontSize   *FontSize          `xml:"font-size,attr,omitempty"`
	FontWeight *FontWeight        `xml:"font-weight,attr,omitempty"`
	Color      *Color             `xml:"color,attr,omitempty"`
}

// Key represents the "key" XSD complex type.
//
// The key type represents a key signature. Both traditional and non-traditional
// key signatures are supported. The optional number attribute refers to staff
// numbers. If absent, the key signature applies to all staves in the part. Key
// signatures appear at the start of each system unless the print-object
// attribute has been set to "no".
type Key struct {
	Cancel  *Cancel     `xml:"cancel,omitempty"`
	Fifths  *Fifths     `xml:"fifths,omitempty"`
	Mode    *Mode       `xml:"mode,omitempty"`
	Content KeyContents `xml:",any"`
	// The optional list of key-octave elements is used to specify in which
	// octave each element of the key signature appears.
	KeyOctave   []KeyOctave  `xml:"key-octave"`
	Number      *StaffNumber `xml:"number,attr,omitempty"`
	DefaultX    *Tenths      `xml:"default-x,attr,omitempty"`
	DefaultY    *Tenths      `xml:"default-y,attr,omitempty"`
	RelativeX   *Tenths      `xml:"relative-x,attr,omitempty"`
	RelativeY   *Tenths      `xml:"relative-y,attr,omitempty"`
	FontFamily  *FontFamily  `xml:"font-family,attr,omitempty"`
	FontStyle   *FontStyle   `xml:"font-style,attr,omitempty"`
	FontSize    *FontSize    `xml:"font-size,attr,omitempty"`
	FontWeight  *FontWeight  `xml:"font-weight,attr,omitempty"`
	Color       *Color       `xml:"color,attr,omitempty"`
	PrintObject *YesNo       `xml:"print-object,attr,omitempty"`
	ID          *string      `xml:"id,attr,omitempty"`
}

// KeyAccidental represents the "key-accidental" XSD complex type.
//
// The key-accidental type indicates the accidental to be displayed in a
// non-traditional key signature, represented in the same manner as the
// accidental type without the formatting attributes.
type KeyAccidental struct {
	Value AccidentalValue           `xml:",chardata"`
	SMuFL *SMuFLAccidentalGlyphName `xml:"smufl,attr,omitempty"`
}

// KeyOctave represents the "key-octave" XSD complex type.
//
// The key-octave type specifies in which octave an element of a key signature
// appears. The content specifies the octave value using the same values as the
// display-octave element. The number attribute is a positive integer that
// refers to the key signature element in left-to-right order. If the cancel
// attribute is set to yes, then this number refers to the canceling key
// signature specified by the cancel element in the parent key element. The
// cancel attribute cannot be set to yes if there is no corresponding cancel
// element within the parent key element. It is no by default.
type KeyOctave struct {
	Value  Octave          `xml:",chardata"`
	Number PositiveInteger `xml:"number,attr"`
	Cancel *YesNo          `xml:"cancel,attr,omitempty"`
}

// Kind represents the "kind" XSD complex type.
//
// Kind indicates the type of chord. Degree elements can then add, subtract, or
// alter from these starting points
//
// The attributes are used to indicate the formatting of the symbol. Since the
// kind element is the constant in all the harmony-chord groups that can make up
// a polychord, many formatting attributes are here.
//
// The use-symbols attribute is yes if the kind should be represented when
// possible with harmony symbols rather than letters and numbers. These symbols
// include:
//   - major: a triangle, like Unicode 25B3
//   - minor: -, like Unicode 002D
//   - augmented: +, like Unicode 002B
//   - diminished: °, like Unicode 00B0
//   - half-diminished: ø, like Unicode 00F8
//
// For the major-minor kind, only the minor symbol is used when use-symbols is
// yes. The major symbol is set using the symbol attribute in the degree-value
// element. The corresponding degree-alter value will usually be 0 in this case.
//
// The text attribute describes how the kind should be spelled in a score. If
// use-symbols is yes, the value of the text attribute follows the symbol. The
// stack-degrees attribute is yes if the degree elements should be stacked above
// each other. The parentheses-degrees attribute is yes if all the degrees
// should be in parentheses. The bracket-degrees attribute is yes if all the
// degrees should be in a bracket. If not specified, these values are
// implementation-specific. The alignment attributes are for the entire
// harmony-chord group of which this kind element is a part.
//
// The text attribute may use strings such as "13sus" that refer to both the
// kind and one or more degree elements. In this case, the corresponding degree
// elements should have the print-object attribute set to "no" to keep redundant
// alterations from being displayed.
type Kind struct {
	Value              KindValue        `xml:",chardata"`
	UseSymbols         *YesNo           `xml:"use-symbols,attr,omitempty"`
	Text               *string          `xml:"text,attr,omitempty"`
	StackDegrees       *YesNo           `xml:"stack-degrees,attr,omitempty"`
	ParenthesesDegrees *YesNo           `xml:"parentheses-degrees,attr,omitempty"`
	BracketDegrees     *YesNo           `xml:"bracket-degrees,attr,omitempty"`
	DefaultX           *Tenths          `xml:"default-x,attr,omitempty"`
	DefaultY           *Tenths          `xml:"default-y,attr,omitempty"`
	RelativeX          *Tenths          `xml:"relative-x,attr,omitempty"`
	RelativeY          *Tenths          `xml:"relative-y,attr,omitempty"`
	FontFamily         *FontFamily      `xml:"font-family,attr,omitempty"`
	FontStyle          *FontStyle       `xml:"font-style,attr,omitempty"`
	FontSize           *FontSize        `xml:"font-size,attr,omitempty"`
	FontWeight         *FontWeight      `xml:"font-weight,attr,omitempty"`
	Color              *Color           `xml:"color,attr,omitempty"`
	Halign             *LeftCenterRight `xml:"halign,attr,omitempty"`
	Valign             *Valign          `xml:"valign,attr,omitempty"`
}

// Level represents the "level" XSD complex type.
//
// The level type is used to specify editorial information for different
// MusicXML elements. The content contains identifying and/or descriptive text
// about the editorial status of the parent element.
//
// If the reference attribute is yes, this indicates editorial information that
// is for display only and should not affect playback. For instance, a modern
// edition of older music may set reference="yes" on the attributes containing
// the music's original clef, key, and time signature. It is no if not
// specified.
//
// The type attribute indicates whether the editorial information applies to the
// start of a series of symbols, the end of a series of symbols, or a single
// symbol. It is single if not specified for compatibility with earlier MusicXML
// versions.
type Level struct {
	Value       string           `xml:",chardata"`
	Reference   *YesNo           `xml:"reference,attr,omitempty"`
	Type        *StartStopSingle `xml:"type,attr,omitempty"`
	Parentheses *YesNo           `xml:"parentheses,attr,omitempty"`
	Bracket     *YesNo           `xml:"bracket,attr,omitempty"`
	Size        *SymbolSize      `xml:"size,attr,omitempty"`
}

// LineDetail represents the "line-detail" XSD complex type.
//
// If the staff-lines element is present, the appearance of each line may be
// individually specified with a line-detail type. Staff lines are numbered from
// bottom to top. The print-object attribute allows lines to be hidden within a
// staff. This is used in special situations such as a widely-spaced percussion
// staff where a note placed below the higher line is distinct from a note
// placed above the lower line. Hidden staff lines are included when specifying
// clef lines and determining display-step / display-octave values, but are not
// counted as lines for the purposes of the system-layout and staff-layout
// elements.
type LineDetail struct {
	Line        StaffLine `xml:"line,attr"`
	Width       *Tenths   `xml:"width,attr,omitempty"`
	Color       *Color    `xml:"color,attr,omitempty"`
	LineType    *LineType `xml:"line-type,attr,omitempty"`
	PrintObject *YesNo    `xml:"print-object,attr,omitempty"`
}

// LineWidth represents the "line-width" XSD complex type.
//
// The line-width type indicates the width of a line type in tenths. The type
// attribute defines what type of line is being defined. Values include beam,
// bracket, dashes, enclosure, ending, extend, heavy barline, leger, light
// barline, octave shift, pedal, slur middle, slur tip, staff, stem, tie middle,
// tie tip, tuplet bracket, and wedge. The text content is expressed in tenths.
type LineWidth struct {
	Value Tenths        `xml:",chardata"`
	Type  LineWidthType `xml:"type,attr"`
}

// Link represents the "link" XSD complex type.
//
// The link type serves as an outgoing simple XLink. If a relative link is used
// within a document that is part of a compressed MusicXML file, the link is
// relative to the root folder of the zip file.
type Link struct {
	Name      *string          `xml:"name,attr,omitempty"`
	Href      string           `xml:"http://www.w3.org/1999/xlink href,attr"`
	Type      *string          `xml:"http://www.w3.org/1999/xlink type,attr,omitempty"`
	Role      *string          `xml:"http://www.w3.org/1999/xlink role,attr,omitempty"`
	Title     *string          `xml:"http://www.w3.org/1999/xlink title,attr,omitempty"`
	Show      *string          `xml:"http://www.w3.org/1999/xlink show,attr,omitempty"`
	Actuate   *string          `xml:"http://www.w3.org/1999/xlink actuate,attr,omitempty"`
	Element   *string          `xml:"element,attr,omitempty"`
	Position  *PositiveInteger `xml:"position,attr,omitempty"`
	DefaultX  *Tenths          `xml:"default-x,attr,omitempty"`
	DefaultY  *Tenths          `xml:"default-y,attr,omitempty"`
	RelativeX *Tenths          `xml:"relative-x,attr,omitempty"`
	RelativeY *Tenths          `xml:"relative-y,attr,omitempty"`
}

// EffectiveType returns Type when explicitly present and the XSD fixed value "simple" otherwise.
func (value *Link) EffectiveType() string {
	if value != nil && value.Type != nil {
		return *value.Type
	}
	return "simple"
}

// TypeMatchesFixed reports whether Type is absent or matches its XSD fixed value "simple" after whitespace normalization.
func (value *Link) TypeMatchesFixed() bool {
	return value == nil || value.Type == nil || normalizeValidationWhitespace("token", string(*value.Type)) == normalizeValidationWhitespace("token", "simple")
}

// EffectiveShow returns Show when explicitly present and the XSD default value "replace" otherwise.
func (value *Link) EffectiveShow() string {
	if value != nil && value.Show != nil {
		return *value.Show
	}
	return "replace"
}

// EffectiveActuate returns Actuate when explicitly present and the XSD default value "onRequest" otherwise.
func (value *Link) EffectiveActuate() string {
	if value != nil && value.Actuate != nil {
		return *value.Actuate
	}
	return "onRequest"
}

// Listen represents the "listen" XSD complex type.
//
// The listen and listening types, new in Version 4.0, specify different ways
// that a score following or machine listening application can interact with a
// performer. The listen type handles interactions that are specific to a note.
// If multiple child elements of the same type are present, they should have
// distinct player and/or time-only attributes.
type Listen struct {
	Content ListenContents `xml:",any"`
}

// Listening represents the "listening" XSD complex type.
//
// The listen and listening types, new in Version 4.0, specify different ways
// that a score following or machine listening application can interact with a
// performer. The listening type handles interactions that change the state of
// the listening application from the specified point in the performance onward.
// If multiple child elements of the same type are present, they should have
// distinct player and/or time-only attributes.
//
// The offset element is used to indicate that the listening change takes place
// offset from the current score position. If the listening element is a child
// of a direction element, the listening offset element overrides the direction
// offset element if both elements are present. Note that the offset reflects
// the intended musical position for the change in state. It should not be used
// to compensate for latency issues in particular hardware configurations.
type Listening struct {
	Content ListeningContents `xml:",any"`
	Offset  *Offset           `xml:"offset,omitempty"`
}

// Lyric represents the "lyric" XSD complex type.
//
// The lyric type represents text underlays for lyrics. Two text elements that
// are not separated by an elision element are part of the same syllable, but
// may have different text formatting. The MusicXML XSD is more strict than the
// DTD in enforcing this by disallowing a second syllabic element unless
// preceded by an elision element. The lyric number indicates multiple lines,
// though a name can be used as well. Common name examples are verse and chorus.
//
// Justification is center by default; placement is below by default. Vertical
// alignment is to the baseline of the text and horizontal alignment matches
// justification. The print-object attribute can override a note's print-lyric
// attribute in cases where only some lyrics on a note are printed, as when
// lyrics for later verses are printed in a block of text rather than with each
// note. The time-only attribute precisely specifies which lyrics are to be sung
// which time through a repeated section.
type Lyric struct {
	Content     LyricContents    `xml:",any"`
	Number      *string          `xml:"number,attr,omitempty"`
	Name        *string          `xml:"name,attr,omitempty"`
	TimeOnly    *TimeOnly        `xml:"time-only,attr,omitempty"`
	Justify     *LeftCenterRight `xml:"justify,attr,omitempty"`
	DefaultX    *Tenths          `xml:"default-x,attr,omitempty"`
	DefaultY    *Tenths          `xml:"default-y,attr,omitempty"`
	RelativeX   *Tenths          `xml:"relative-x,attr,omitempty"`
	RelativeY   *Tenths          `xml:"relative-y,attr,omitempty"`
	Placement   *AboveBelow      `xml:"placement,attr,omitempty"`
	Color       *Color           `xml:"color,attr,omitempty"`
	PrintObject *YesNo           `xml:"print-object,attr,omitempty"`
	ID          *string          `xml:"id,attr,omitempty"`
}

// LyricFont represents the "lyric-font" XSD complex type.
//
// The lyric-font type specifies the default font for a particular name and
// number of lyric.
type LyricFont struct {
	Number     *string     `xml:"number,attr,omitempty"`
	Name       *string     `xml:"name,attr,omitempty"`
	FontFamily *FontFamily `xml:"font-family,attr,omitempty"`
	FontStyle  *FontStyle  `xml:"font-style,attr,omitempty"`
	FontSize   *FontSize   `xml:"font-size,attr,omitempty"`
	FontWeight *FontWeight `xml:"font-weight,attr,omitempty"`
}

// LyricLanguage represents the "lyric-language" XSD complex type.
//
// The lyric-language type specifies the default language for a particular name
// and number of lyric.
type LyricLanguage struct {
	Number *string `xml:"number,attr,omitempty"`
	Name   *string `xml:"name,attr,omitempty"`
	Lang   string  `xml:"http://www.w3.org/XML/1998/namespace lang,attr"`
}

// MeasureLayout represents the "measure-layout" XSD complex type.
//
// The measure-layout type includes the horizontal distance from the previous
// measure. It applies to the current measure only.
type MeasureLayout struct {
	// The measure-distance element specifies the horizontal distance from the
	// previous measure. This value is only used for systems where there is
	// horizontal whitespace in the middle of a system, as in systems with
	// codas. To specify the measure width, use the width attribute of the
	// measure element.
	MeasureDistance *Tenths `xml:"measure-distance,omitempty"`
}

// MeasureNumbering represents the "measure-numbering" XSD complex type.
//
// The measure-numbering type describes how frequently measure numbers are
// displayed on this part. The text attribute from the measure element is used
// for display, or the number attribute if the text attribute is not present.
// Measures with an implicit attribute set to "yes" never display a measure
// number, regardless of the measure-numbering setting.
//
// The optional staff attribute refers to staff numbers within the part, from
// top to bottom on the system. It indicates which staff is used as the
// reference point for vertical positioning. A value of 1 is assumed if not
// present.
//
// The optional multiple-rest-always and multiple-rest-range attributes describe
// how measure numbers are shown on multiple rests when the measure-numbering
// value is not set to none. The multiple-rest-always attribute is set to yes
// when the measure number should always be shown, even if the multiple rest
// starts midway through a system when measure numbering is set to system level.
// The multiple-rest-range attribute is set to yes when measure numbers on
// multiple rests display the range of numbers for the first and last measure,
// rather than just the number of the first measure.
type MeasureNumbering struct {
	Value              MeasureNumberingValue `xml:",chardata"`
	System             *SystemRelationNumber `xml:"system,attr,omitempty"`
	Staff              *StaffNumber          `xml:"staff,attr,omitempty"`
	MultipleRestAlways *YesNo                `xml:"multiple-rest-always,attr,omitempty"`
	MultipleRestRange  *YesNo                `xml:"multiple-rest-range,attr,omitempty"`
	DefaultX           *Tenths               `xml:"default-x,attr,omitempty"`
	DefaultY           *Tenths               `xml:"default-y,attr,omitempty"`
	RelativeX          *Tenths               `xml:"relative-x,attr,omitempty"`
	RelativeY          *Tenths               `xml:"relative-y,attr,omitempty"`
	FontFamily         *FontFamily           `xml:"font-family,attr,omitempty"`
	FontStyle          *FontStyle            `xml:"font-style,attr,omitempty"`
	FontSize           *FontSize             `xml:"font-size,attr,omitempty"`
	FontWeight         *FontWeight           `xml:"font-weight,attr,omitempty"`
	Color              *Color                `xml:"color,attr,omitempty"`
	Halign             *LeftCenterRight      `xml:"halign,attr,omitempty"`
	Valign             *Valign               `xml:"valign,attr,omitempty"`
}

// MeasureRepeat represents the "measure-repeat" XSD complex type.
//
// The measure-repeat type is used for both single and multiple measure repeats.
// The text of the element indicates the number of measures to be repeated in a
// single pattern. The slashes attribute specifies the number of slashes to use
// in the repeat sign. It is 1 if not specified. The text of the element is
// ignored when the type is stop.
//
// The stop type indicates the first measure where the repeats are no longer
// displayed. Both the start and the stop of the measure-repeat should be
// specified unless the repeats are displayed through the end of the part.
//
// The measure-repeat element specifies a notation style for repetitions. The
// actual music being repeated needs to be repeated within each measure of the
// MusicXML file. This element specifies the notation that indicates the repeat.
type MeasureRepeat struct {
	Value   PositiveIntegerOrEmpty `xml:",chardata"`
	Type    StartStop              `xml:"type,attr"`
	Slashes *PositiveInteger       `xml:"slashes,attr,omitempty"`
}

// MeasureStyle represents the "measure-style" XSD complex type.
//
// A measure-style indicates a special way to print partial to multiple measures
// within a part. This includes multiple rests over several measures, repeats of
// beats, single, or multiple measures, and use of slash notation.
//
// The multiple-rest and measure-repeat elements indicate the number of measures
// covered in the element content. The beat-repeat and slash elements can cover
// partial measures. All but the multiple-rest element use a type attribute to
// indicate starting and stopping the use of the style. The optional number
// attribute specifies the staff number from top to bottom on the system, as
// with clef.
type MeasureStyle struct {
	MultipleRest  *MultipleRest  `xml:"multiple-rest,omitempty"`
	MeasureRepeat *MeasureRepeat `xml:"measure-repeat,omitempty"`
	BeatRepeat    *BeatRepeat    `xml:"beat-repeat,omitempty"`
	Slash         *Slash         `xml:"slash,omitempty"`
	Number        *StaffNumber   `xml:"number,attr,omitempty"`
	FontFamily    *FontFamily    `xml:"font-family,attr,omitempty"`
	FontStyle     *FontStyle     `xml:"font-style,attr,omitempty"`
	FontSize      *FontSize      `xml:"font-size,attr,omitempty"`
	FontWeight    *FontWeight    `xml:"font-weight,attr,omitempty"`
	Color         *Color         `xml:"color,attr,omitempty"`
	ID            *string        `xml:"id,attr,omitempty"`
}

// Membrane represents the "membrane" XSD complex type.
//
// The membrane type represents pictograms for membrane percussion instruments.
// The smufl attribute is used to distinguish different SMuFL stylistic
// alternates.
type Membrane struct {
	Value MembraneValue            `xml:",chardata"`
	SMuFL *SMuFLPictogramGlyphName `xml:"smufl,attr,omitempty"`
}

// Metal represents the "metal" XSD complex type.
//
// The metal type represents pictograms for metal percussion instruments. The
// smufl attribute is used to distinguish different SMuFL stylistic alternates.
type Metal struct {
	Value MetalValue               `xml:",chardata"`
	SMuFL *SMuFLPictogramGlyphName `xml:"smufl,attr,omitempty"`
}

// Metronome represents the "metronome" XSD complex type.
//
// The metronome type represents metronome marks and other metric relationships.
// The beat-unit group and per-minute element specify regular metronome marks.
// The metronome-note and metronome-relation elements allow for the
// specification of metric modulations and other metric relationships, such as
// swing tempo marks where two eighths are equated to a quarter note / eighth
// note triplet. Tied notes can be represented in both types of metronome marks
// by using the beat-unit-tied and metronome-tied elements. The parentheses
// attribute indicates whether or not to put the metronome mark in parentheses;
// its value is no if not specified. The print-object attribute is set to no in
// cases where the metronome element represents a relationship or range that is
// not displayed in the music notation.
type Metronome struct {
	Content     MetronomeContents `xml:",any"`
	Parentheses *YesNo            `xml:"parentheses,attr,omitempty"`
	DefaultX    *Tenths           `xml:"default-x,attr,omitempty"`
	DefaultY    *Tenths           `xml:"default-y,attr,omitempty"`
	RelativeX   *Tenths           `xml:"relative-x,attr,omitempty"`
	RelativeY   *Tenths           `xml:"relative-y,attr,omitempty"`
	FontFamily  *FontFamily       `xml:"font-family,attr,omitempty"`
	FontStyle   *FontStyle        `xml:"font-style,attr,omitempty"`
	FontSize    *FontSize         `xml:"font-size,attr,omitempty"`
	FontWeight  *FontWeight       `xml:"font-weight,attr,omitempty"`
	Color       *Color            `xml:"color,attr,omitempty"`
	Halign      *LeftCenterRight  `xml:"halign,attr,omitempty"`
	Valign      *Valign           `xml:"valign,attr,omitempty"`
	PrintObject *YesNo            `xml:"print-object,attr,omitempty"`
	Justify     *LeftCenterRight  `xml:"justify,attr,omitempty"`
	ID          *string           `xml:"id,attr,omitempty"`
}

// MetronomeBeam represents the "metronome-beam" XSD complex type.
//
// The metronome-beam type works like the beam type in defining metric
// relationships, but does not include all the attributes available in the beam
// type.
type MetronomeBeam struct {
	Value  BeamValue  `xml:",chardata"`
	Number *BeamLevel `xml:"number,attr,omitempty"`
}

// EffectiveNumber returns Number when explicitly present and the XSD default value "1" otherwise.
func (value *MetronomeBeam) EffectiveNumber() BeamLevel {
	if value != nil && value.Number != nil {
		return *value.Number
	}
	return 1
}

// MetronomeNote represents the "metronome-note" XSD complex type.
//
// The metronome-note type defines the appearance of a note within a metric
// relationship mark.
type MetronomeNote struct {
	// The metronome-type element works like the type element in defining metric
	// relationships.
	MetronomeType NoteTypeValue `xml:"metronome-type"`
	// The metronome-dot element works like the dot element in defining metric
	// relationships.
	MetronomeDot    []Empty          `xml:"metronome-dot"`
	MetronomeBeam   []MetronomeBeam  `xml:"metronome-beam"`
	MetronomeTied   *MetronomeTied   `xml:"metronome-tied,omitempty"`
	MetronomeTuplet *MetronomeTuplet `xml:"metronome-tuplet,omitempty"`
}

// MetronomeTied represents the "metronome-tied" XSD complex type.
//
// The metronome-tied indicates the presence of a tie within a metric
// relationship mark. As with the tied element, both the start and stop of the
// tie should be specified, in this case within separate metronome-note
// elements.
type MetronomeTied struct {
	Type StartStop `xml:"type,attr"`
}

// MetronomeTuplet represents the "metronome-tuplet" XSD complex type.
//
// The metronome-tuplet type uses the same element structure as the
// time-modification element along with some attributes from the tuplet element.
type MetronomeTuplet struct {
	TimeModification
	Type       StartStop   `xml:"type,attr"`
	Bracket    *YesNo      `xml:"bracket,attr,omitempty"`
	ShowNumber *ShowTuplet `xml:"show-number,attr,omitempty"`
}

// MIDIDevice represents the "midi-device" XSD complex type.
//
// The midi-device type corresponds to the DeviceName meta event in Standard
// MIDI Files. The optional port attribute is a number from 1 to 16 that can be
// used with the unofficial MIDI 1.0 port (or cable) meta event. Unlike the
// DeviceName meta event, there can be multiple midi-device elements per
// MusicXML part. The optional id attribute refers to the score-instrument
// assigned to this device. If missing, the device assignment affects all
// score-instrument elements in the score-part.
type MIDIDevice struct {
	Value string  `xml:",chardata"`
	Port  *MIDI16 `xml:"port,attr,omitempty"`
	ID    *string `xml:"id,attr,omitempty"`
}

// MIDIInstrument represents the "midi-instrument" XSD complex type.
//
// The midi-instrument type defines MIDI 1.0 instrument playback. The
// midi-instrument element can be a part of either the score-instrument element
// at the start of a part, or the sound element within a part. The id attribute
// refers to the score-instrument affected by the change.
type MIDIInstrument struct {
	// The midi-channel element specifies a MIDI 1.0 channel numbers ranging
	// from 1 to 16.
	MIDIChannel *MIDI16 `xml:"midi-channel,omitempty"`
	// The midi-name element corresponds to a ProgramName meta-event within a
	// Standard MIDI File.
	MIDIName *string `xml:"midi-name,omitempty"`
	// The midi-bank element specifies a MIDI 1.0 bank number ranging from 1 to
	// 16,384.
	MIDIBank *MIDI16384 `xml:"midi-bank,omitempty"`
	// The midi-program element specifies a MIDI 1.0 program number ranging from
	// 1 to 128.
	MIDIProgram *MIDI128 `xml:"midi-program,omitempty"`
	// For unpitched instruments, the midi-unpitched element specifies a MIDI
	// 1.0 note number ranging from 1 to 128. It is usually used with MIDI banks
	// for percussion. Note that MIDI 1.0 note numbers are generally specified
	// from 0 to 127 rather than the 1 to 128 numbering used in this element.
	MIDIUnpitched *MIDI128 `xml:"midi-unpitched,omitempty"`
	// The volume element value is a percentage of the maximum ranging from 0 to
	// 100, with decimal values allowed. This corresponds to a scaling value for
	// the MIDI 1.0 channel volume controller.
	Volume *Percent `xml:"volume,omitempty"`
	// The pan and elevation elements allow placing of sound in a 3-D space
	// relative to the listener. Both are expressed in degrees ranging from -180
	// to 180. For pan, 0 is straight ahead, -90 is hard left, 90 is hard right,
	// and -180 and 180 are directly behind the listener.
	Pan *RotationDegrees `xml:"pan,omitempty"`
	// The elevation and pan elements allow placing of sound in a 3-D space
	// relative to the listener. Both are expressed in degrees ranging from -180
	// to 180. For elevation, 0 is level with the listener, 90 is directly
	// above, and -90 is directly below.
	Elevation *RotationDegrees `xml:"elevation,omitempty"`
	ID        string           `xml:"id,attr"`
}

// Miscellaneous represents the "miscellaneous" XSD complex type.
//
// If a program has other metadata not yet supported in the MusicXML format, it
// can go in the miscellaneous element. The miscellaneous type puts each
// separate part of metadata into its own miscellaneous-field type.
type Miscellaneous struct {
	MiscellaneousField []MiscellaneousField `xml:"miscellaneous-field"`
}

// MiscellaneousField represents the "miscellaneous-field" XSD complex type.
//
// If a program has other metadata not yet supported in the MusicXML format,
// each type of metadata can go in a miscellaneous-field element. The required
// name attribute indicates the type of metadata the element content represents.
type MiscellaneousField struct {
	Value string `xml:",chardata"`
	Name  string `xml:"name,attr"`
}

// Mordent represents the "mordent" XSD complex type.
//
// The mordent type is used for both represents the mordent sign with the
// vertical line and the inverted-mordent sign without the line. The long
// attribute is "no" by default. The approach and departure attributes are used
// for compound ornaments, indicating how the beginning and ending of the
// ornament look relative to the main part of the mordent.
type Mordent struct {
	EmptyTrillSound
	Long      *YesNo      `xml:"long,attr,omitempty"`
	Approach  *AboveBelow `xml:"approach,attr,omitempty"`
	Departure *AboveBelow `xml:"departure,attr,omitempty"`
}

// MultipleRest represents the "multiple-rest" XSD complex type.
//
// The text of the multiple-rest type indicates the number of measures in the
// multiple rest. Multiple rests may use the 1-bar / 2-bar / 4-bar rest symbols,
// or a single shape. The use-symbols attribute indicates which to use; it is no
// if not specified.
type MultipleRest struct {
	Value      PositiveInteger `xml:",chardata"`
	UseSymbols *YesNo          `xml:"use-symbols,attr,omitempty"`
}

// NameDisplay represents the "name-display" XSD complex type.
//
// The name-display type is used for exact formatting of multi-font text in part
// and group names to the left of the system. The print-object attribute can be
// used to determine what, if anything, is printed at the start of each system.
// Enclosure for the display-text element is none by default. Language for the
// display-text element is Italian ("it") by default.
type NameDisplay struct {
	Content     NameDisplayContents `xml:",any"`
	PrintObject *YesNo              `xml:"print-object,attr,omitempty"`
}

// NonArpeggiate represents the "non-arpeggiate" XSD complex type.
//
// The non-arpeggiate type indicates that this note is at the top or bottom of a
// bracket indicating to not arpeggiate these notes. Since this does not involve
// playback, it is only used on the top or bottom notes, not on each note as for
// the arpeggiate type.
type NonArpeggiate struct {
	Type      TopBottom    `xml:"type,attr"`
	Number    *NumberLevel `xml:"number,attr,omitempty"`
	DefaultX  *Tenths      `xml:"default-x,attr,omitempty"`
	DefaultY  *Tenths      `xml:"default-y,attr,omitempty"`
	RelativeX *Tenths      `xml:"relative-x,attr,omitempty"`
	RelativeY *Tenths      `xml:"relative-y,attr,omitempty"`
	Placement *AboveBelow  `xml:"placement,attr,omitempty"`
	Color     *Color       `xml:"color,attr,omitempty"`
	ID        *string      `xml:"id,attr,omitempty"`
}

// Notations represents the "notations" XSD complex type.
//
// Notations refer to musical notations, not XML notations. Multiple notations
// are allowed in order to represent multiple editorial levels. The print-object
// attribute, added in Version 3.0, allows notations to represent details of
// performance technique, such as fingerings, without having them appear in the
// score.
type Notations struct {
	Footnote    *FormattedText    `xml:"footnote,omitempty"`
	Level       *Level            `xml:"level,omitempty"`
	Content     NotationsContents `xml:",any"`
	PrintObject *YesNo            `xml:"print-object,attr,omitempty"`
	ID          *string           `xml:"id,attr,omitempty"`
}

// Note represents the "note" XSD complex type.
//
// Notes are the most common type of MusicXML data. The MusicXML format
// distinguishes between elements used for sound information and elements used
// for notation information (e.g., tie is used for sound, tied for notation).
// Thus grace notes do not have a duration element. Cue notes have a duration
// element, as do forward elements, but no tie elements. Having these two types
// of information available can make interchange easier, as some programs handle
// one type of information more readily than the other.
//
// The print-leger attribute is used to indicate whether leger lines are
// printed. Notes without leger lines are used to indicate indeterminate high
// and low notes. By default, it is set to yes. If print-object is set to no,
// print-leger is interpreted to also be set to no if not present. This
// attribute is ignored for rests.
//
// The dynamics and end-dynamics attributes correspond to MIDI 1.0's Note On and
// Note Off velocities, respectively. They are expressed in terms of percentages
// of the default forte value (90 for MIDI 1.0).
//
// The attack and release attributes are used to alter the starting and stopping
// time of the note from when it would otherwise occur based on the flow of
// durations - information that is specific to a performance. They are expressed
// in terms of divisions, either positive or negative. A note that starts a tie
// should not have a release attribute, and a note that stops a tie should not
// have an attack attribute. The attack and release attributes are independent
// of each other. The attack attribute only changes the starting time of a note,
// and the release attribute only changes the stopping time of a note.
//
// If a note is played only particular times through a repeat, the time-only
// attribute shows which times to play the note.
//
// The pizzicato attribute is used when just this note is sounded pizzicato, vs.
// the pizzicato element which changes overall playback between pizzicato and
// arco.
type Note struct {
	Grace *Grace `xml:"grace,omitempty"`
	// The cue element indicates the presence of a cue note. In MusicXML, a cue
	// note is a silent note with no playback. Normal notes that play can be
	// specified as cue size using the type element. A cue note that is
	// specified as full size using the type element will still remain silent.
	Cue *Empty `xml:"cue,omitempty"`
	// The chord element indicates that this note is an additional chord tone
	// with the preceding note.
	//
	// The duration of a chord note does not move the musical position within a
	// measure. That is done by the duration of the first preceding note without
	// a chord element. Thus the duration of a chord note cannot be longer than
	// the preceding note.
	//
	// In most cases the duration will be the same as the preceding note.
	// However it can be shorter in situations such as multiple stops for string
	// instruments.
	Chord     *Empty     `xml:"chord,omitempty"`
	Pitch     *Pitch     `xml:"pitch,omitempty"`
	Unpitched *Unpitched `xml:"unpitched,omitempty"`
	Rest      *Rest      `xml:"rest,omitempty"`
	// Duration is a positive number specified in division units. This is the
	// intended duration vs. notated duration (for instance, differences in
	// dotted notes in Baroque-era music). Differences in duration specific to
	// an interpretation or performance should be represented using the note
	// element's attack and release attributes.
	//
	// The duration element moves the musical position when used in backup
	// elements, forward elements, and note elements that do not contain a chord
	// child element.
	Duration   *PositiveDivisions `xml:"duration,omitempty"`
	Tie        []Tie              `xml:"tie"`
	Instrument []Instrument       `xml:"instrument"`
	Footnote   *FormattedText     `xml:"footnote,omitempty"`
	Level      *Level             `xml:"level,omitempty"`
	Voice      *string            `xml:"voice,omitempty"`
	Type       *NoteType          `xml:"type,omitempty"`
	// One dot element is used for each dot of prolongation. The placement
	// attribute is used to specify whether the dot should appear above or below
	// the staff line. It is ignored for notes that appear on a staff space.
	Dot              []EmptyPlacement  `xml:"dot"`
	Accidental       *Accidental       `xml:"accidental,omitempty"`
	TimeModification *TimeModification `xml:"time-modification,omitempty"`
	Stem             *Stem             `xml:"stem,omitempty"`
	Notehead         *Notehead         `xml:"notehead,omitempty"`
	NoteheadText     *NoteheadText     `xml:"notehead-text,omitempty"`
	// Staff assignment is only needed for music notated on multiple staves.
	// Used by both notes and directions. Staff values are numbers, with 1
	// referring to the top-most staff in a part.
	Staff        *PositiveInteger    `xml:"staff,omitempty"`
	Beam         []Beam              `xml:"beam"`
	Notations    []Notations         `xml:"notations"`
	Lyric        []Lyric             `xml:"lyric"`
	Play         *Play               `xml:"play,omitempty"`
	Listen       *Listen             `xml:"listen,omitempty"`
	PrintLeger   *YesNo              `xml:"print-leger,attr,omitempty"`
	Dynamics     *NonNegativeDecimal `xml:"dynamics,attr,omitempty"`
	EndDynamics  *NonNegativeDecimal `xml:"end-dynamics,attr,omitempty"`
	Attack       *Divisions          `xml:"attack,attr,omitempty"`
	Release      *Divisions          `xml:"release,attr,omitempty"`
	TimeOnly     *TimeOnly           `xml:"time-only,attr,omitempty"`
	Pizzicato    *YesNo              `xml:"pizzicato,attr,omitempty"`
	DefaultX     *Tenths             `xml:"default-x,attr,omitempty"`
	DefaultY     *Tenths             `xml:"default-y,attr,omitempty"`
	RelativeX    *Tenths             `xml:"relative-x,attr,omitempty"`
	RelativeY    *Tenths             `xml:"relative-y,attr,omitempty"`
	FontFamily   *FontFamily         `xml:"font-family,attr,omitempty"`
	FontStyle    *FontStyle          `xml:"font-style,attr,omitempty"`
	FontSize     *FontSize           `xml:"font-size,attr,omitempty"`
	FontWeight   *FontWeight         `xml:"font-weight,attr,omitempty"`
	Color        *Color              `xml:"color,attr,omitempty"`
	PrintDot     *YesNo              `xml:"print-dot,attr,omitempty"`
	PrintLyric   *YesNo              `xml:"print-lyric,attr,omitempty"`
	PrintObject  *YesNo              `xml:"print-object,attr,omitempty"`
	PrintSpacing *YesNo              `xml:"print-spacing,attr,omitempty"`
	ID           *string             `xml:"id,attr,omitempty"`
}

// NoteSize represents the "note-size" XSD complex type.
//
// The note-size type indicates the percentage of the regular note size to use
// for notes with a cue and large size as defined in the type element. The grace
// type is used for notes of cue size that that include a grace element. The cue
// type is used for all other notes with cue size, whether defined explicitly or
// implicitly via a cue element. The large type is used for notes of large size.
// The text content represent the numeric percentage. A value of 100 would be
// identical to the size of a regular note as defined by the music font.
type NoteSize struct {
	Value NonNegativeDecimal `xml:",chardata"`
	Type  NoteSizeType       `xml:"type,attr"`
}

// NoteType represents the "note-type" XSD complex type.
//
// The note-type type indicates the graphic note type. Values range from 1024th
// to maxima. The size attribute indicates full, cue, grace-cue, or large size.
// The default is full for regular notes, grace-cue for notes that contain both
// grace and cue elements, and cue for notes that contain either a cue or a
// grace element, but not both.
type NoteType struct {
	Value NoteTypeValue `xml:",chardata"`
	Size  *SymbolSize   `xml:"size,attr,omitempty"`
}

// Notehead represents the "notehead" XSD complex type.
//
// The notehead type indicates shapes other than the open and closed ovals
// associated with note durations.
//
// The smufl attribute can be used to specify a particular notehead, allowing
// application interoperability without requiring every SMuFL glyph to have a
// MusicXML element equivalent. This attribute can be used either with the
// "other" value, or to refine a specific notehead value such as "cluster".
// Noteheads in the SMuFL Note name noteheads and Note name noteheads supplement
// ranges (U+E150–U+E1AF and U+EEE0–U+EEFF) should not use the smufl
// attribute or the "other" value, but instead use the notehead-text element.
//
// For the enclosed shapes, the default is to be hollow for half notes and
// longer, and filled otherwise. The filled attribute can be set to change this
// if needed.
//
// If the parentheses attribute is set to yes, the notehead is parenthesized. It
// is no by default.
type Notehead struct {
	Value       NoteheadValue   `xml:",chardata"`
	Filled      *YesNo          `xml:"filled,attr,omitempty"`
	Parentheses *YesNo          `xml:"parentheses,attr,omitempty"`
	FontFamily  *FontFamily     `xml:"font-family,attr,omitempty"`
	FontStyle   *FontStyle      `xml:"font-style,attr,omitempty"`
	FontSize    *FontSize       `xml:"font-size,attr,omitempty"`
	FontWeight  *FontWeight     `xml:"font-weight,attr,omitempty"`
	Color       *Color          `xml:"color,attr,omitempty"`
	SMuFL       *SMuFLGlyphName `xml:"smufl,attr,omitempty"`
}

// NoteheadText represents the "notehead-text" XSD complex type.
//
// The notehead-text type represents text that is displayed inside a notehead,
// as is done in some educational music. It is not needed for the numbers used
// in tablature or jianpu notation. The presence of a TAB or jianpu clefs is
// sufficient to indicate that numbers are used. The display-text and
// accidental-text elements allow display of fully formatted text and
// accidentals.
type NoteheadText struct {
	Content NoteheadTextContents `xml:",any"`
}

// Numeral represents the "numeral" XSD complex type.
//
// The numeral type represents the Roman numeral or Nashville number part of a
// harmony. It requires that the key be specified in the encoding, either with a
// key or numeral-key element.
type Numeral struct {
	NumeralRoot NumeralRoot `xml:"numeral-root"`
	// The numeral-alter element represents an alteration to the numeral-root,
	// similar to the alter element for a pitch. The print-object attribute can
	// be used to hide an alteration in cases such as when the MusicXML encoding
	// of a 6 or 7 numeral-root in a minor key requires an alteration that is
	// not displayed. The location attribute indicates whether the alteration
	// should appear to the left or the right of the numeral-root. It is left by
	// default.
	NumeralAlter *HarmonyAlter `xml:"numeral-alter,omitempty"`
	NumeralKey   *NumeralKey   `xml:"numeral-key,omitempty"`
}

// NumeralKey represents the "numeral-key" XSD complex type.
//
// The numeral-key type is used when the key for the numeral is different than
// the key specified by the key signature. The numeral-fifths element specifies
// the key in the same way as the fifths element. The numeral-mode element
// specifies the mode similar to the mode element, but with a restricted set of
// values
type NumeralKey struct {
	NumeralFifths Fifths      `xml:"numeral-fifths"`
	NumeralMode   NumeralMode `xml:"numeral-mode"`
	PrintObject   *YesNo      `xml:"print-object,attr,omitempty"`
}

// NumeralRoot represents the "numeral-root" XSD complex type.
//
// The numeral-root type represents the Roman numeral or Nashville number as a
// positive integer from 1 to 7. The text attribute indicates how the numeral
// should appear in the score. A numeral-root value of 5 with a kind of major
// would have a text attribute of "V" if displayed as a Roman numeral, and "5"
// if displayed as a Nashville number. If the text attribute is not specified,
// the display is application-dependent.
type NumeralRoot struct {
	Value      NumeralValue `xml:",chardata"`
	Text       *string      `xml:"text,attr,omitempty"`
	DefaultX   *Tenths      `xml:"default-x,attr,omitempty"`
	DefaultY   *Tenths      `xml:"default-y,attr,omitempty"`
	RelativeX  *Tenths      `xml:"relative-x,attr,omitempty"`
	RelativeY  *Tenths      `xml:"relative-y,attr,omitempty"`
	FontFamily *FontFamily  `xml:"font-family,attr,omitempty"`
	FontStyle  *FontStyle   `xml:"font-style,attr,omitempty"`
	FontSize   *FontSize    `xml:"font-size,attr,omitempty"`
	FontWeight *FontWeight  `xml:"font-weight,attr,omitempty"`
	Color      *Color       `xml:"color,attr,omitempty"`
}

// OctaveShift represents the "octave-shift" XSD complex type.
//
// The octave shift type indicates where notes are shifted up or down from their
// true pitched values because of printing difficulty. Thus a treble clef line
// noted with 8va will be indicated with an octave-shift down from the pitch
// data indicated in the notes. A size of 8 indicates one octave; a size of 15
// indicates two octaves.
type OctaveShift struct {
	Type        UpDownStopContinue `xml:"type,attr"`
	Number      *NumberLevel       `xml:"number,attr,omitempty"`
	Size        *PositiveInteger   `xml:"size,attr,omitempty"`
	DashLength  *Tenths            `xml:"dash-length,attr,omitempty"`
	SpaceLength *Tenths            `xml:"space-length,attr,omitempty"`
	DefaultX    *Tenths            `xml:"default-x,attr,omitempty"`
	DefaultY    *Tenths            `xml:"default-y,attr,omitempty"`
	RelativeX   *Tenths            `xml:"relative-x,attr,omitempty"`
	RelativeY   *Tenths            `xml:"relative-y,attr,omitempty"`
	FontFamily  *FontFamily        `xml:"font-family,attr,omitempty"`
	FontStyle   *FontStyle         `xml:"font-style,attr,omitempty"`
	FontSize    *FontSize          `xml:"font-size,attr,omitempty"`
	FontWeight  *FontWeight        `xml:"font-weight,attr,omitempty"`
	Color       *Color             `xml:"color,attr,omitempty"`
	ID          *string            `xml:"id,attr,omitempty"`
}

// EffectiveSize returns Size when explicitly present and the XSD default value "8" otherwise.
func (value *OctaveShift) EffectiveSize() PositiveInteger {
	if value != nil && value.Size != nil {
		return *value.Size
	}
	return 8
}

// Offset represents the "offset" XSD complex type.
//
// An offset is represented in terms of divisions, and indicates where the
// direction will appear relative to the current musical location. The current
// musical location is always within the current measure, even at the end of a
// measure.
//
// The offset affects the visual appearance of the direction. If the sound
// attribute is "yes", then the offset affects playback and listening too. If
// the sound attribute is "no", then any sound or listening associated with the
// direction takes effect at the current location. The sound attribute is "no"
// by default for compatibility with earlier versions of the MusicXML format. If
// an element within a direction includes a default-x attribute, the offset
// value will be ignored when determining the appearance of that element.
type Offset struct {
	Value Divisions `xml:",chardata"`
	Sound *YesNo    `xml:"sound,attr,omitempty"`
}

// Opus represents the "opus" XSD complex type.
//
// The opus type represents a link to a MusicXML opus document that composes
// multiple MusicXML scores into a collection.
type Opus struct {
	Href    string  `xml:"http://www.w3.org/1999/xlink href,attr"`
	Type    *string `xml:"http://www.w3.org/1999/xlink type,attr,omitempty"`
	Role    *string `xml:"http://www.w3.org/1999/xlink role,attr,omitempty"`
	Title   *string `xml:"http://www.w3.org/1999/xlink title,attr,omitempty"`
	Show    *string `xml:"http://www.w3.org/1999/xlink show,attr,omitempty"`
	Actuate *string `xml:"http://www.w3.org/1999/xlink actuate,attr,omitempty"`
}

// EffectiveType returns Type when explicitly present and the XSD fixed value "simple" otherwise.
func (value *Opus) EffectiveType() string {
	if value != nil && value.Type != nil {
		return *value.Type
	}
	return "simple"
}

// TypeMatchesFixed reports whether Type is absent or matches its XSD fixed value "simple" after whitespace normalization.
func (value *Opus) TypeMatchesFixed() bool {
	return value == nil || value.Type == nil || normalizeValidationWhitespace("token", string(*value.Type)) == normalizeValidationWhitespace("token", "simple")
}

// EffectiveShow returns Show when explicitly present and the XSD default value "replace" otherwise.
func (value *Opus) EffectiveShow() string {
	if value != nil && value.Show != nil {
		return *value.Show
	}
	return "replace"
}

// EffectiveActuate returns Actuate when explicitly present and the XSD default value "onRequest" otherwise.
func (value *Opus) EffectiveActuate() string {
	if value != nil && value.Actuate != nil {
		return *value.Actuate
	}
	return "onRequest"
}

// Ornaments represents the "ornaments" XSD complex type.
//
// Ornaments can be any of several types, followed optionally by accidentals.
// The accidental-mark element's content is represented the same as an
// accidental element, but with a different name to reflect the different
// musical meaning.
type Ornaments struct {
	Content OrnamentsContents `xml:",any"`
	ID      *string           `xml:"id,attr,omitempty"`
}

// OtherAppearance represents the "other-appearance" XSD complex type.
//
// The other-appearance type is used to define any graphical settings not yet in
// the current version of the MusicXML format. This allows extended
// representation, though without application interoperability.
type OtherAppearance struct {
	Value string `xml:",chardata"`
	Type  string `xml:"type,attr"`
}

// OtherDirection represents the "other-direction" XSD complex type.
//
// The other-direction type is used to define any direction symbols not yet in
// the MusicXML format. The smufl attribute can be used to specify a particular
// direction symbol, allowing application interoperability without requiring
// every SMuFL glyph to have a MusicXML element equivalent. Using the
// other-direction type without the smufl attribute allows for extended
// representation, though without application interoperability.
type OtherDirection struct {
	Value       string           `xml:",chardata"`
	PrintObject *YesNo           `xml:"print-object,attr,omitempty"`
	DefaultX    *Tenths          `xml:"default-x,attr,omitempty"`
	DefaultY    *Tenths          `xml:"default-y,attr,omitempty"`
	RelativeX   *Tenths          `xml:"relative-x,attr,omitempty"`
	RelativeY   *Tenths          `xml:"relative-y,attr,omitempty"`
	FontFamily  *FontFamily      `xml:"font-family,attr,omitempty"`
	FontStyle   *FontStyle       `xml:"font-style,attr,omitempty"`
	FontSize    *FontSize        `xml:"font-size,attr,omitempty"`
	FontWeight  *FontWeight      `xml:"font-weight,attr,omitempty"`
	Color       *Color           `xml:"color,attr,omitempty"`
	Halign      *LeftCenterRight `xml:"halign,attr,omitempty"`
	Valign      *Valign          `xml:"valign,attr,omitempty"`
	SMuFL       *SMuFLGlyphName  `xml:"smufl,attr,omitempty"`
	ID          *string          `xml:"id,attr,omitempty"`
}

// OtherListening represents the "other-listening" XSD complex type.
//
// The other-listening type represents other types of listening control and
// interaction. The required type attribute indicates the type of listening to
// which the element content applies. The optional player and time-only
// attributes restrict the element to apply to a single player or set of times
// through a repeated section, respectively.
type OtherListening struct {
	Value    string    `xml:",chardata"`
	Type     string    `xml:"type,attr"`
	Player   *string   `xml:"player,attr,omitempty"`
	TimeOnly *TimeOnly `xml:"time-only,attr,omitempty"`
}

// OtherNotation represents the "other-notation" XSD complex type.
//
// The other-notation type is used to define any notations not yet in the
// MusicXML format. It handles notations where more specific extension elements
// such as other-dynamics and other-technical are not appropriate. The smufl
// attribute can be used to specify a particular notation, allowing application
// interoperability without requiring every SMuFL glyph to have a MusicXML
// element equivalent. Using the other-notation type without the smufl attribute
// allows for extended representation, though without application
// interoperability.
type OtherNotation struct {
	Value       string          `xml:",chardata"`
	Type        StartStopSingle `xml:"type,attr"`
	Number      *NumberLevel    `xml:"number,attr,omitempty"`
	PrintObject *YesNo          `xml:"print-object,attr,omitempty"`
	DefaultX    *Tenths         `xml:"default-x,attr,omitempty"`
	DefaultY    *Tenths         `xml:"default-y,attr,omitempty"`
	RelativeX   *Tenths         `xml:"relative-x,attr,omitempty"`
	RelativeY   *Tenths         `xml:"relative-y,attr,omitempty"`
	FontFamily  *FontFamily     `xml:"font-family,attr,omitempty"`
	FontStyle   *FontStyle      `xml:"font-style,attr,omitempty"`
	FontSize    *FontSize       `xml:"font-size,attr,omitempty"`
	FontWeight  *FontWeight     `xml:"font-weight,attr,omitempty"`
	Color       *Color          `xml:"color,attr,omitempty"`
	Placement   *AboveBelow     `xml:"placement,attr,omitempty"`
	SMuFL       *SMuFLGlyphName `xml:"smufl,attr,omitempty"`
	ID          *string         `xml:"id,attr,omitempty"`
}

// EffectiveNumber returns Number when explicitly present and the XSD default value "1" otherwise.
func (value *OtherNotation) EffectiveNumber() NumberLevel {
	if value != nil && value.Number != nil {
		return *value.Number
	}
	return 1
}

// OtherPlacementText represents the "other-placement-text" XSD complex type.
//
// The other-placement-text type represents a text element with print-style,
// placement, and smufl attribute groups. This type is used by MusicXML notation
// extension elements to allow specification of specific SMuFL glyphs without
// needed to add every glyph as a MusicXML element.
type OtherPlacementText struct {
	Value      string          `xml:",chardata"`
	DefaultX   *Tenths         `xml:"default-x,attr,omitempty"`
	DefaultY   *Tenths         `xml:"default-y,attr,omitempty"`
	RelativeX  *Tenths         `xml:"relative-x,attr,omitempty"`
	RelativeY  *Tenths         `xml:"relative-y,attr,omitempty"`
	FontFamily *FontFamily     `xml:"font-family,attr,omitempty"`
	FontStyle  *FontStyle      `xml:"font-style,attr,omitempty"`
	FontSize   *FontSize       `xml:"font-size,attr,omitempty"`
	FontWeight *FontWeight     `xml:"font-weight,attr,omitempty"`
	Color      *Color          `xml:"color,attr,omitempty"`
	Placement  *AboveBelow     `xml:"placement,attr,omitempty"`
	SMuFL      *SMuFLGlyphName `xml:"smufl,attr,omitempty"`
}

// OtherPlay represents the "other-play" XSD complex type.
//
// The other-play element represents other types of playback. The required type
// attribute indicates the type of playback to which the element content
// applies.
type OtherPlay struct {
	Value string `xml:",chardata"`
	Type  string `xml:"type,attr"`
}

// OtherText represents the "other-text" XSD complex type.
//
// The other-text type represents a text element with a smufl attribute group.
// This type is used by MusicXML direction extension elements to allow
// specification of specific SMuFL glyphs without needed to add every glyph as a
// MusicXML element.
type OtherText struct {
	Value string          `xml:",chardata"`
	SMuFL *SMuFLGlyphName `xml:"smufl,attr,omitempty"`
}

// PageLayout represents the "page-layout" XSD complex type.
//
// Page layout can be defined both in score-wide defaults and in the print
// element. Page margins are specified either for both even and odd pages, or
// via separate odd and even page number values. The type is not needed when
// used as part of a print element. If omitted when used in the defaults
// element, "both" is the default.
//
// If no page-layout element is present in the defaults element, default page
// layout values are chosen by the application.
//
// When used in the print element, the page-layout element affects the
// appearance of the current page only. All other pages use the default values
// as determined by the defaults element. If any child elements are missing from
// the page-layout element in a print element, the values determined by the
// defaults element are used there as well.
type PageLayout struct {
	PageHeight  *Tenths       `xml:"page-height,omitempty"`
	PageWidth   *Tenths       `xml:"page-width,omitempty"`
	PageMargins []PageMargins `xml:"page-margins"`
}

// PageMargins represents the "page-margins" XSD complex type.
//
// Page margins are specified either for both even and odd pages, or via
// separate odd and even page number values. The type attribute is not needed
// when used as part of a print element. If omitted when the page-margins type
// is used in the defaults element, "both" is the default value.
type PageMargins struct {
	LeftMargin   Tenths      `xml:"left-margin"`
	RightMargin  Tenths      `xml:"right-margin"`
	TopMargin    Tenths      `xml:"top-margin"`
	BottomMargin Tenths      `xml:"bottom-margin"`
	Type         *MarginType `xml:"type,attr,omitempty"`
}

// PartClef represents the "part-clef" XSD complex type.
//
// The child elements of the part-clef type have the same meaning as for the
// clef type. However that meaning applies to a transposed part created from the
// existing score file.
type PartClef struct {
	// The sign element represents the clef symbol.
	Sign ClefSign `xml:"sign"`
	// Line numbers are counted from the bottom of the staff. They are only
	// needed with the G, F, and C signs in order to position a pitch correctly
	// on the staff. Standard values are 2 for the G sign (treble clef), 4 for
	// the F sign (bass clef), and 3 for the C sign (alto clef). Line values can
	// be used to specify positions outside the staff, such as a C clef
	// positioned in the middle of a grand staff.
	Line *StaffLinePosition `xml:"line,omitempty"`
	// The clef-octave-change element is used for transposing clefs. A treble
	// clef for tenors would have a value of -1.
	ClefOctaveChange *Integer `xml:"clef-octave-change,omitempty"`
}

// PartGroup represents the "part-group" XSD complex type.
//
// The part-group element indicates groupings of parts in the score, usually
// indicated by braces and brackets. Braces that are used for multi-staff parts
// should be defined in the attributes element for that part. The part-group
// start element appears before the first score-part in the group. The
// part-group stop element appears after the last score-part in the group.
//
// The number attribute is used to distinguish overlapping and nested
// part-groups, not the sequence of groups. As with parts, groups can have a
// name and abbreviation. Values for the child elements are ignored at the stop
// of a group.
//
// A part-group element is not needed for a single multi-staff part. By default,
// multi-staff parts include a brace symbol and (if appropriate given the
// bar-style) common barlines. The symbol formatting for a multi-staff part can
// be more fully specified using the part-symbol element.
type PartGroup struct {
	GroupName *GroupName `xml:"group-name,omitempty"`
	// Formatting specified in the group-name-display element overrides
	// formatting specified in the group-name element.
	GroupNameDisplay  *NameDisplay `xml:"group-name-display,omitempty"`
	GroupAbbreviation *GroupName   `xml:"group-abbreviation,omitempty"`
	// Formatting specified in the group-abbreviation-display element overrides
	// formatting specified in the group-abbreviation element.
	GroupAbbreviationDisplay *NameDisplay  `xml:"group-abbreviation-display,omitempty"`
	GroupSymbol              *GroupSymbol  `xml:"group-symbol,omitempty"`
	GroupBarline             *GroupBarline `xml:"group-barline,omitempty"`
	// The group-time element indicates that the displayed time signatures
	// should stretch across all parts and staves in the group.
	GroupTime *Empty         `xml:"group-time,omitempty"`
	Footnote  *FormattedText `xml:"footnote,omitempty"`
	Level     *Level         `xml:"level,omitempty"`
	Type      StartStop      `xml:"type,attr"`
	Number    *string        `xml:"number,attr,omitempty"`
}

// EffectiveNumber returns Number when explicitly present and the XSD default value "1" otherwise.
func (value *PartGroup) EffectiveNumber() string {
	if value != nil && value.Number != nil {
		return *value.Number
	}
	return "1"
}

// PartLink represents the "part-link" XSD complex type.
//
// The part-link type allows MusicXML data for both score and parts to be
// contained within a single compressed MusicXML file. It links a score-part
// from a score document to MusicXML documents that contain parts data. In the
// case of a single compressed MusicXML file, the link href values are paths
// that are relative to the root folder of the zip file.
type PartLink struct {
	InstrumentLink []InstrumentLink `xml:"instrument-link"`
	// Multiple part-link elements can reference different types of linked
	// documents, such as parts and condensed score. The optional group-link
	// elements identify the groups used in the linked document. The content of
	// a group-link element should match the content of a group element in the
	// linked document.
	GroupLink []string `xml:"group-link"`
	Href      string   `xml:"http://www.w3.org/1999/xlink href,attr"`
	Type      *string  `xml:"http://www.w3.org/1999/xlink type,attr,omitempty"`
	Role      *string  `xml:"http://www.w3.org/1999/xlink role,attr,omitempty"`
	Title     *string  `xml:"http://www.w3.org/1999/xlink title,attr,omitempty"`
	Show      *string  `xml:"http://www.w3.org/1999/xlink show,attr,omitempty"`
	Actuate   *string  `xml:"http://www.w3.org/1999/xlink actuate,attr,omitempty"`
}

// EffectiveType returns Type when explicitly present and the XSD fixed value "simple" otherwise.
func (value *PartLink) EffectiveType() string {
	if value != nil && value.Type != nil {
		return *value.Type
	}
	return "simple"
}

// TypeMatchesFixed reports whether Type is absent or matches its XSD fixed value "simple" after whitespace normalization.
func (value *PartLink) TypeMatchesFixed() bool {
	return value == nil || value.Type == nil || normalizeValidationWhitespace("token", string(*value.Type)) == normalizeValidationWhitespace("token", "simple")
}

// EffectiveShow returns Show when explicitly present and the XSD default value "replace" otherwise.
func (value *PartLink) EffectiveShow() string {
	if value != nil && value.Show != nil {
		return *value.Show
	}
	return "replace"
}

// EffectiveActuate returns Actuate when explicitly present and the XSD default value "onRequest" otherwise.
func (value *PartLink) EffectiveActuate() string {
	if value != nil && value.Actuate != nil {
		return *value.Actuate
	}
	return "onRequest"
}

// PartList represents the "part-list" XSD complex type.
//
// The part-list identifies the different musical parts in this document. Each
// part has an ID that is used later within the musical data. Since parts may be
// encoded separately and combined later, identification elements are present at
// both the score and score-part levels. There must be at least one score-part,
// combined as desired with part-group elements that indicate braces and
// brackets. Parts are ordered from top to bottom in a score based on the order
// in which they appear in the part-list.
type PartList struct {
	Content PartListContents `xml:",any"`
}

// PartName represents the "part-name" XSD complex type.
//
// The part-name type describes the name or abbreviation of a score-part
// element. Formatting attributes for the part-name element are deprecated in
// Version 2.0 in favor of the new part-name-display and
// part-abbreviation-display elements.
type PartName struct {
	Value       string           `xml:",chardata"`
	DefaultX    *Tenths          `xml:"default-x,attr,omitempty"`
	DefaultY    *Tenths          `xml:"default-y,attr,omitempty"`
	RelativeX   *Tenths          `xml:"relative-x,attr,omitempty"`
	RelativeY   *Tenths          `xml:"relative-y,attr,omitempty"`
	FontFamily  *FontFamily      `xml:"font-family,attr,omitempty"`
	FontStyle   *FontStyle       `xml:"font-style,attr,omitempty"`
	FontSize    *FontSize        `xml:"font-size,attr,omitempty"`
	FontWeight  *FontWeight      `xml:"font-weight,attr,omitempty"`
	Color       *Color           `xml:"color,attr,omitempty"`
	PrintObject *YesNo           `xml:"print-object,attr,omitempty"`
	Justify     *LeftCenterRight `xml:"justify,attr,omitempty"`
}

// PartSymbol represents the "part-symbol" XSD complex type.
//
// The part-symbol type indicates how a symbol for a multi-staff part is
// indicated in the score; brace is the default value. The top-staff and
// bottom-staff attributes are used when the brace does not extend across the
// entire part. For example, in a 3-staff organ part, the top-staff will
// typically be 1 for the right hand, while the bottom-staff will typically be 2
// for the left hand. Staff 3 for the pedals is usually outside the brace. By
// default, the presence of a part-symbol element that does not extend across
// the entire part also indicates a corresponding change in the common barlines
// within a part.
type PartSymbol struct {
	Value       GroupSymbolValue `xml:",chardata"`
	TopStaff    *StaffNumber     `xml:"top-staff,attr,omitempty"`
	BottomStaff *StaffNumber     `xml:"bottom-staff,attr,omitempty"`
	DefaultX    *Tenths          `xml:"default-x,attr,omitempty"`
	DefaultY    *Tenths          `xml:"default-y,attr,omitempty"`
	RelativeX   *Tenths          `xml:"relative-x,attr,omitempty"`
	RelativeY   *Tenths          `xml:"relative-y,attr,omitempty"`
	Color       *Color           `xml:"color,attr,omitempty"`
}

// PartTranspose represents the "part-transpose" XSD complex type.
//
// The child elements of the part-transpose type have the same meaning as for
// the transpose type. However that meaning applies to a transposed part created
// from the existing score file.
type PartTranspose struct {
	// The diatonic element specifies the number of pitch steps needed to go
	// from written to sounding pitch. This allows for correct spelling of
	// enharmonic transpositions. This value does not include octave-change
	// values; the values for both elements need to be added to the written
	// pitch to get the correct sounding pitch.
	Diatonic *Integer `xml:"diatonic,omitempty"`
	// The chromatic element represents the number of semitones needed to get
	// from written to sounding pitch. This value does not include octave-change
	// values; the values for both elements need to be added to the written
	// pitch to get the correct sounding pitch.
	Chromatic Semitones `xml:"chromatic"`
	// The octave-change element indicates how many octaves to add to get from
	// written pitch to sounding pitch. The octave-change element should be
	// included when using transposition intervals of an octave or more, and
	// should not be present for intervals of less than an octave.
	OctaveChange *Integer `xml:"octave-change,omitempty"`
	// If the double element is present, it indicates that the music is doubled
	// one octave from what is currently written.
	Double *Double `xml:"double,omitempty"`
}

// Pedal represents the "pedal" XSD complex type.
//
// The pedal type represents piano pedal marks, including damper and sostenuto
// pedal marks. The line attribute is yes if pedal lines are used. The sign
// attribute is yes if Ped, Sost, and * signs are used. For compatibility with
// older versions, the sign attribute is yes by default if the line attribute is
// no, and is no by default if the line attribute is yes. If the sign attribute
// is set to yes and the type is start or sostenuto, the abbreviated attribute
// is yes if the short P and S signs are used, and no if the full Ped and Sost
// signs are used. It is no by default. Otherwise the abbreviated attribute is
// ignored. The alignment attributes are ignored if the sign attribute is no.
