type StaffDivide struct {
	Type       StaffDivideSymbol `xml:"type,attr"`
	DefaultX   *Tenths           `xml:"default-x,attr,omitempty"`
	DefaultY   *Tenths           `xml:"default-y,attr,omitempty"`
	RelativeX  *Tenths           `xml:"relative-x,attr,omitempty"`
	RelativeY  *Tenths           `xml:"relative-y,attr,omitempty"`
	FontFamily *FontFamily       `xml:"font-family,attr,omitempty"`
	FontStyle  *FontStyle        `xml:"font-style,attr,omitempty"`
	FontSize   *FontSize         `xml:"font-size,attr,omitempty"`
	FontWeight *FontWeight       `xml:"font-weight,attr,omitempty"`
	Color      *Color            `xml:"color,attr,omitempty"`
	Halign     *LeftCenterRight  `xml:"halign,attr,omitempty"`
	Valign     *Valign           `xml:"valign,attr,omitempty"`
	ID         *string           `xml:"id,attr,omitempty"`
}

// StaffLayout represents the "staff-layout" XSD complex type.
//
// Staff layout includes the vertical distance from the bottom line of the
// previous staff in this system to the top line of the staff specified by the
// number attribute. The optional number attribute refers to staff numbers
// within the part, from top to bottom on the system. A value of 1 is used if
// not present.
//
// When used in the defaults element, the values apply to all systems in all
// parts. When used in the print element, the values apply to the current system
// only. This value is ignored for the first staff in a system.
type StaffLayout struct {
	StaffDistance *Tenths      `xml:"staff-distance,omitempty"`
	Number        *StaffNumber `xml:"number,attr,omitempty"`
}

// StaffSize represents the "staff-size" XSD complex type.
//
// The staff-size element indicates how large a staff space is on this staff,
// expressed as a percentage of the work's default scaling. Values less than 100
// make the staff space smaller while values over 100 make the staff space
// larger. A staff-type of cue, ossia, or editorial implies a staff-size of less
// than 100, but the exact value is implementation-dependent unless specified
// here. Staff size affects staff height only, not the relationship of the staff
// to the left and right margins.
//
// In some cases, a staff-size different than 100 also scales the notation on
// the staff, such as with a cue staff. In other cases, such as percussion
// staves, the lines may be more widely spaced without scaling the notation on
// the staff. The scaling attribute allows these two cases to be distinguished.
// It specifies the percentage scaling that applies to the notation. Values less
// that 100 make the notation smaller while values over 100 make the notation
// larger. The staff-size content and scaling attribute are both non-negative
// decimal values.
type StaffSize struct {
	Value   NonNegativeDecimal  `xml:",chardata"`
	Scaling *NonNegativeDecimal `xml:"scaling,attr,omitempty"`
}

// StaffTuning represents the "staff-tuning" XSD complex type.
//
// The staff-tuning type specifies the open, non-capo tuning of the lines on a
// tablature staff.
type StaffTuning struct {
	// The tuning-step element is represented like the step element, with a
	// different name to reflect its different function in string tuning.
	TuningStep Step `xml:"tuning-step"`
	// The tuning-alter element is represented like the alter element, with a
	// different name to reflect its different function in string tuning.
	TuningAlter *Semitones `xml:"tuning-alter,omitempty"`
	// The tuning-octave element is represented like the octave element, with a
	// different name to reflect its different function in string tuning.
	TuningOctave Octave    `xml:"tuning-octave"`
	Line         StaffLine `xml:"line,attr"`
}

// Stem represents the "stem" XSD complex type.
