// TupletType represents the "tuplet-type" XSD complex type.
//
// The tuplet-type type indicates the graphical note type of the notes for this
// portion of the tuplet.
type TupletType struct {
	Value      NoteTypeValue `xml:",chardata"`
	FontFamily *FontFamily   `xml:"font-family,attr,omitempty"`
	FontStyle  *FontStyle    `xml:"font-style,attr,omitempty"`
	FontSize   *FontSize     `xml:"font-size,attr,omitempty"`
	FontWeight *FontWeight   `xml:"font-weight,attr,omitempty"`
	Color      *Color        `xml:"color,attr,omitempty"`
}

// TypedText represents the "typed-text" XSD complex type.
//
// The typed-text type represents a text element with a type attribute.
type TypedText struct {
	Value string  `xml:",chardata"`
	Type  *string `xml:"type,attr,omitempty"`
}

// Unpitched represents the "unpitched" XSD complex type.
//
// The unpitched type represents musical elements that are notated on the staff
// but lack definite pitch, such as unpitched percussion and speaking voice. If
// the child elements are not present, the note is placed on the middle line of
