type VirtualInstrument struct {
	// The virtual-library element indicates the virtual instrument library
	// name.
	VirtualLibrary *string `xml:"virtual-library,omitempty"`
	// The virtual-name element indicates the library-specific name for the
	// virtual instrument.
	VirtualName *string `xml:"virtual-name,omitempty"`
}

// Wait represents the "wait" XSD complex type.
//
// The wait type specifies a point where the accompaniment should wait for a
// performer event before continuing. This typically happens at the start of new
// sections or after a held note or indeterminate music. These waiting points
// cannot always be inferred reliably from the contents of the displayed score.
// The optional player and time-only attributes restrict the type to apply to a
// single player or set of times through a repeated section, respectively.
type Wait struct {
	Player   *string   `xml:"player,attr,omitempty"`
	TimeOnly *TimeOnly `xml:"time-only,attr,omitempty"`
}

// WavyLine represents the "wavy-line" XSD complex type.
//
// Wavy lines are one way to indicate trills and vibrato. When used with a
